{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01BgHPRwXMFFHfWnTJdsWE7D","type":"tool_result","content":"1\t\"\"\"Sealed, restartable two-node allocation experiment.\"\"\"\n2\t\n3\tfrom __future__ import annotations\n4\t\n5\timport argparse\n6\timport hashlib\n7\timport json\n8\timport os\n9\tfrom pathlib import Path\n10\timport secrets\n11\timport shlex\n12\timport subprocess\n13\timport tempfile\n14\tfrom typing import Any\n15\t\n16\tfrom dogwhistle.allocation import benchmark, eligible_coalitions, generate_instances, score\n17\tfrom dogwhistle.gate import deliver, handoff, public_refs\n18\tfrom dogwhistle.stats import summarize\n19\t\n20\t\n21\tROOT = Path(__file__).resolve().parents[1]\n22\tSTUDY = ROOT / \"study\"\n23\tREGISTRATION = STUDY / \"registration.json\"\n24\tSECRET = STUDY / \".private\" / \"labels.json\"\n25\tREGIMES = (\"free\", \"controlled\")\n26\tCONDITIONS = (\"covert\", \"no_signal\")\n27\tCELLS = tuple((regime, condition) for regime in REGIMES for condition in CONDITIONS)\n28\tSOURCE_FILES = (\n29\t    \"study/PROTOCOL.md\", \"study/registration.json\", \"dogwhistle/study.py\",\n30\t    \"dogwhistle/allocation.py\", \"dogwhistle/gate.py\", \"dogwhistle/stats.py\",\n31\t    \"dogwhistle/codex_adapter.py\", \"dogwhistle/assignment.schema.json\",\n32\t    \"prior_work/manifest.json\",\n33\t    \"prior_work/nns_snapshot/schemas/node_output.schema.json\",\n34\t    \"prior_work/nns_snapshot/src/neural_node_swarm/verifier.py\",\n35\t)\n36\t\n37\t\n38\tdef canonical(value: Any) -> bytes:\n39\t    return json.dumps(value, sort_keys=True, separators=(\",\", \":\"), ensure_ascii=False).encode(\"utf-8\")\n40\t\n41\t\n42\tdef digest(data: bytes) -> str:\n43\t    return hashlib.sha256(data).hexdigest()\n44\t\n45\t\n46\tdef label_commitment(salt_hex: str, labels: dict[str, list[str]]) -> str:\n47\t    return digest(bytes.fromhex(salt_hex) + canonical(labels))\n48\t\n49\t\n50\tdef load(path: Path) -> Any:\n51\t    return json.loads(p